CREATE TABLE villes (
    ID_ville INT PRIMARY KEY,
    ville_departement VARCHAR(30),
    ville_nom_maj VARCHAR(30),
    ville_nom VARCHAR(30),
    ville_code_postal VARCHAR(30),
    ville_longitude_deg VARCHAR(30),
    ville_latitude_deg VARCHAR(30),
    ville_longitude_grd VARCHAR(30),
    ville_latitude_grd VARCHAR(30),
    ville_longitude_dms VARCHAR(30),
    ville_latitude_dms VARCHAR(30),
    ville_zmin VARCHAR(30),
    ville_zmax VARCHAR(30)
);


